class VerifyFailure(Exception):
    pass

def phi(n):
    if n < 1:
        raise VerifyFailure('domain')
    r, m = n, n
    p = 2
    while p * p <= m:
        if m % p == 0:
            r -= r // p
            while m % p == 0:
                m //= p
        p += 1
    if m > 1:
        r -= r // m
    return r

def frac_cmp(n1, d1, n2, d2):
    return n1 * d2 - n2 * d1

def require(cond, msg):
    if not cond:
        raise VerifyFailure(msg)

def run(w):
    M = w['M']
    require(M == 256, 'M')
    lo, hi = w['image_range']
    require((lo, hi) == (8, 50), 'range')

    image = set()
    nmin = {}
    for m in range(1, M + 1):
        v = phi(m)
        if lo <= v <= hi:
            image.add(v)
            if v not in nmin:
                nmin[v] = m

    ntab = {int(k): int(v) for k, v in w['n_table'].items()}
    require(set(ntab.keys()) == image, 'witness keys != recomputed image')
    for a in image:
        require(ntab[a] == nmin[a], 'n_a mismatch at a=%d' % a)
        require(phi(ntab[a]) == a, 'phi(n_a)!=a at a=%d' % a)
        for m in range(1, ntab[a]):
            require(phi(m) != a, 'leastness fails at a=%d' % a)

    for a in w['declared_nontotients_in_range']:
        require(a not in image, 'declared nontotient %d has preimage' % a)
        require(a not in ntab, 'nontotient in table')

    best_r_num, best_r_den, best_a = 0, 1, None
    for a in image:
        rn, rd = ntab[a], a
        require(frac_cmp(rn, rd, 15, 8) <= 0, 'ratio bound fails at a=%d' % a)
        if best_a is None or frac_cmp(rn, rd, best_r_num, best_r_den) > 0:
            best_r_num, best_r_den, best_a = rn, rd, a
    require((best_r_num, best_r_den, best_a) == (15, 8, 8),
            'max ratio not 15/8 at a=8')

    for a_s, n_s in w['anchors'].items():
        a, n = int(a_s), int(n_s)
        if lo <= a <= hi:
            require(ntab[a] == n, 'anchor a=%d' % a)
        else:
            require(phi(n) == a, 'anchor phi(%d)=%d' % (n, a))

    return True

def verify(witness):
    return run(witness)
